var o=[{title:`Parti dai tuoi giorni liberi`,text:`Scegli i giorni in cui puoi davvero allenarti prima di scegliere una split complicata. Con due giorni, un programma total body il lunedì e il giovedì lascia diversi giorni di recupero tra le sessioni. Con tre, lunedì, mercoledì e venerdì è semplice. Con quattro, puoi distribuire nella settimana due sessioni per la parte alta e due per la parte bassa. Sono esempi, e funzionano anche altre disposizioni.`},{title:`Recupero tra sessioni correlate`,text:`Molti principianti si trovano bene con circa uno o due giorni tra allenamenti duri per gli stessi muscoli, soprattutto finché il dolore muscolare è ancora una novità per loro. Le 48 ore spesso citate sono una linea guida pratica. La tua storia di allenamento, lo sforzo, la scelta degli esercizi e il sonno cambiano tutti quanto recupero ti serve.`},{title:`Dove mettere il lavoro duro`,text:`I sollevamenti pesanti e quelli che richiedono molta abilità vanno meglio quando sei abbastanza fresco. Hinge, squat molto impegnativi e intervalli di sprint in giorni consecutivi possono accumulare una fatica di cui non hai bisogno. Camminate facili o lavoro di mobilità possono stare tra i giorni di forza e non contano come un altro allenamento duro.`},{title:`Una settimana flessibile`,text:`Se salti un allenamento, spostalo in un giorno libero o prosegui con la sessione successiva. Non concentrare in un giorno solo tutto il lavoro saltato e non accatastare sessioni dure per lo stesso movimento solo per raggiungere un numero settimanale. Monitora prestazioni e fatica nell’arco di diverse settimane. Non serve lo stesso volume in ogni settimana di calendario.`},{title:`Usare TrainUp`,text:`In Profilo imposti quanti giorni a settimana ti alleni, quanto dura una sessione e quali giorni preferisci, e puoi cambiarli in qualsiasi momento. Dalla Dashboard puoi attivare i promemoria degli allenamenti per i giorni e gli orari che hai scelto. Lo Storico mostra i tuoi allenamenti di questa settimana, il tuo sforzo medio e un grafico di 4 settimane, che ti aiuta a seguire la fatica nelle varie settimane.`}];var a=[{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: indicazioni su forza e flessibilità`,url:`https://www.nhs.uk/live-well/exercise/how-to-improve-strength-flexibility/`},{label:`NSCA: sicurezza e fondamenti dell’allenamento coi pesi`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var t={sections:o,sources:a};export{t as default,o as sections,a as sources};